/* GeoFact exploration cards — 195/195 concise flag notes.
   Sources are retained per card for re-audit. Existing official-source cards are preserved;
   the remaining cards point to the CIA World Factbook 2024 archive flag entries. */
(function(root){
  'use strict';
  root.GeoFactFlagCards = {
    AFG:{fr:"L’Afghanistan a changé de drapeau national de nombreuses fois à l’époque moderne ; le drapeau blanc utilisé par les autorités talibanes de facto porte la chahada en noir.",en:"Afghanistan has changed national flags many times in the modern era; the white flag used by the de facto Taliban authorities bears the shahada in black.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/afghanistan/flag/"},
    ALB:{fr:"L’aigle noir à deux têtes rappelle l’emblème associé au dirigeant du XVe siècle Skanderbeg, sur fond rouge.",en:"The black double-headed eagle recalls the emblem associated with 15th-century leader Skanderbeg, set on a red field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/albania/flag/"},
    DZA:{fr:"Le drapeau associe le vert et le blanc à un croissant et une étoile rouges, des symboles fortement liés à l’identité islamique et nationale de l’Algérie.",en:"The flag combines green and white with a red crescent and star, symbols strongly associated with Algeria’s Islamic and national identity.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/algeria/flag/"},
    AND:{fr:"Le tricolore vertical bleu-jaune-rouge porte les armoiries nationales au centre, ce qui le distingue de tricolores similaires.",en:"The vertical blue-yellow-red tricolour carries the national coat of arms in its centre, distinguishing it from similar tricolours.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/andorra/flag/"},
    AGO:{fr:"Une demi-roue dentée et une machette jaunes se croisent sous une étoile, des symboles liés aux travailleurs, à la production et à la solidarité internationale.",en:"A yellow half gear and machete cross on the flag with a star above them, symbols linked to workers, production and international solidarity.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/angola/flag/"},
    ATG:{fr:"Le soleil levant représente l’aube d’une nouvelle ère ; la composition en V rend aussi le drapeau d’Antigua-et-Barbuda particulièrement reconnaissable.",en:"The rising sun represents the dawn of a new era; the V-shaped design also makes Antigua and Barbuda’s flag unusually distinctive.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/antigua-and-barbuda/flag/"},
    ARG:{fr:"Le Soleil de Mai au centre renvoie à la révolution de Mai de 1810, étape majeure vers l’indépendance argentine.",en:"The Sun of May at the centre refers to the May Revolution of 1810, a key step toward Argentine independence.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/argentina/flag/"},
    ARM:{fr:"Le tricolore rouge-bleu-orange de l’Arménie fut utilisé par la Première République en 1918 puis restauré après l’indépendance vis-à-vis de l’Union soviétique.",en:"Armenia’s red-blue-orange tricolour was first used by the short-lived First Republic in 1918 and restored after independence from the Soviet Union.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/armenia/flag/"},
    AUS:{fr:"Le dessin est issu d’un concours lancé lors de la fédération australienne en 1901. Cinq propositions presque identiques ont partagé le premier prix ; l’étoile du Commonwealth a reçu un septième rayon en 1908.",en:"The design came from a competition launched when Australia federated in 1901. Five near-identical entries shared first prize; a seventh point was added to the Commonwealth Star in 1908.",source:"https://www.pmc.gov.au/honours-and-symbols/australian-national-symbols/australian-national-flag"},
    AUT:{fr:"La bannière rouge-blanc-rouge de l’Autriche compte parmi les plus anciens motifs de drapeau national d’Europe et est traditionnellement liée à la dynastie des Babenberg.",en:"Austria’s red-white-red banner is among Europe’s oldest national flag designs and is traditionally linked to the Babenberg dynasty.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/austria/flag/"},
    AZE:{fr:"Le croissant et l’étoile à huit branches figurent sur un tricolore bleu-rouge-vert ; le drapeau moderne reprend le dessin de la république de 1918-1920.",en:"The crescent and eight-pointed star sit on a blue-red-green tricolour; the modern flag revives the design used by the 1918–1920 republic.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/azerbaijan/flag/"},
    BHS:{fr:"Le triangle noir représente l’unité et la détermination du peuple bahaméen, tandis que l’aigue-marine et l’or évoquent la mer et le soleil.",en:"The black triangle represents the unity and determination of the Bahamian people, while aquamarine and gold evoke the sea and sun.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/bahamas-the/flag/"},
    BHR:{fr:"Les champs blanc et rouge de Bahreïn sont séparés par cinq pointes blanches, nombre associé aux cinq piliers de l’islam.",en:"Bahrain’s white and red fields are separated by five white points, a number associated with the Five Pillars of Islam.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/bahrain/flag/"},
    BGD:{fr:"Le disque rouge est volontairement légèrement décalé vers la hampe afin de paraître centré lorsque le drapeau flotte.",en:"The red disc is deliberately placed slightly toward the hoist so that it appears centred when the flag is flying.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/bangladesh/flag/"},
    BRB:{fr:"Le trident brisé symbolise la rupture de la Barbade avec la domination coloniale ; il dérive du trident figurant autrefois sur l’insigne colonial.",en:"The broken trident head symbolises Barbados’s break from colonial rule; it is derived from the trident once shown on the colonial badge.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/barbados/flag/"},
    BLR:{fr:"Le drapeau biélorusse comporte près de la hampe un motif ornemental traditionnel rouge et blanc, adapté d’un dessin textile.",en:"Belarus’s flag includes a traditional red-and-white ornamental pattern at the hoist, adapted from a textile design.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/belarus/flag/"},
    BEL:{fr:"Les couleurs noir-jaune-rouge viennent des armes de l’ancien duché de Brabant et deviennent couleurs nationales lors de la révolution de 1830.",en:"Belgium’s black-yellow-red colours come from the arms of the historic Duchy of Brabant and became national colours during the 1830 revolution.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/belgium/flag/"},
    BLZ:{fr:"Le Belize est le seul État souverain dont le drapeau national représente de façon très visible des personnages humains : deux travailleurs encadrent les armoiries.",en:"Belize is the only sovereign country whose national flag prominently depicts human figures: two workers flank the coat of arms.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/belize/flag/"},
    BEN:{fr:"Le Bénin a rétabli son drapeau vert-jaune-rouge en 1990 après avoir abandonné le drapeau vert à étoile rouge de la période marxiste.",en:"Benin restored its green-yellow-red flag in 1990 after abandoning the Marxist-era green flag with a red star.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/benin/flag/"},
    BTN:{fr:"Le drapeau du Bhoutan est partagé en diagonale entre jaune et orange et montre le Druk, le Dragon-Tonnerre blanc qui donne au pays son nom local.",en:"Bhutan’s flag is divided diagonally between yellow and orange and features the Druk, the white Thunder Dragon that gives the country its local name.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/bhutan/flag/"},
    BOL:{fr:"Le tricolore rouge-jaune-vert de la Bolivie date de 1851 ; le drapeau d’État ajoute les armoiries nationales sur la bande jaune centrale.",en:"Bolivia’s red-yellow-green tricolour dates from 1851; the state flag adds the national coat of arms to the central yellow band.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/bolivia/flag/"},
    BIH:{fr:"Le triangle jaune rappelle approximativement la forme de la Bosnie-Herzégovine ; ses trois pointes sont couramment associées aux trois peuples constitutifs du pays.",en:"The yellow triangle roughly echoes the shape of Bosnia and Herzegovina, while its three points are commonly linked to the country’s three constituent peoples.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/bosnia-and-herzegovina/flag/"},
    BWA:{fr:"Le Botswana a choisi le bleu clair pour l’eau et des bandes noires et blanches pour l’harmonie raciale ; le dessin fut adopté à l’indépendance en 1966.",en:"Botswana chose light blue for water and black-and-white stripes for racial harmony; the design was adopted at independence in 1966.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/botswana/flag/"},
    BRA:{fr:"Les étoiles reproduisent le ciel de Rio de Janeiro le 15 novembre 1889, jour de la proclamation de la République ; chacune représente un État ou le District fédéral.",en:"The stars reproduce the sky over Rio de Janeiro on 15 November 1889, the day the republic was proclaimed, with each star representing a state or the Federal District.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/brazil/flag/"},
    BRN:{fr:"Le drapeau jaune du Brunei porte l’emblème national sur des diagonales blanche et noire ; le jaune est traditionnellement associé au sultan.",en:"Brunei’s yellow flag carries the national crest over diagonal white and black bands; yellow is traditionally associated with the sultan.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/brunei/flag/"},
    BGR:{fr:"La Bulgarie a remplacé le bleu panslave par le vert dans son tricolore blanc-vert-rouge après avoir obtenu son autonomie au XIXe siècle.",en:"Bulgaria replaced the pan-Slavic blue with green in its white-green-red tricolour after gaining autonomy in the 19th century.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/bulgaria/flag/"},
    BFA:{fr:"Le Burkina Faso adopte son drapeau rouge et vert en 1984, lorsque la Haute-Volta change de nom ; une étoile jaune se trouve au centre.",en:"Burkina Faso adopted its red-green flag in 1984 when the country changed its name from Upper Volta; a yellow star sits at the centre.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/burkina-faso/flag/"},
    BDI:{fr:"Le drapeau du Burundi place trois étoiles à six branches dans un disque blanc, traditionnellement associées à la devise nationale : Unité, Travail, Progrès.",en:"Burundi’s flag places three six-pointed stars in a white disc, traditionally associated with the national motto: Unity, Work, Progress.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/burundi/flag/"},
    CPV:{fr:"Les dix étoiles du Cap-Vert représentent ses dix îles principales, disposées en cercle sur des bandes bleues, blanches et rouges.",en:"Cabo Verde’s ten stars represent its ten main islands, arranged in a circle across blue, white and red bands.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/cabo-verde/flag/"},
    KHM:{fr:"Le Cambodge est l’un des rares pays à placer un bâtiment sur son drapeau : l’emblème central représente Angkor Wat.",en:"Cambodia is one of the few countries to place a building on its flag: the central emblem depicts Angkor Wat.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/cambodia/flag/"},
    CMR:{fr:"L’étoile jaune centrale du tricolore vert-rouge-jaune du Cameroun est appelée « étoile de l’unité ».",en:"The central yellow star on Cameroon’s green-red-yellow tricolour is known as the Star of Unity.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/cameroon/flag/"},
    CAN:{fr:"Le drapeau à la feuille d’érable a été proclamé officiellement le 28 janvier 1965 et hissé pour la première fois sur la Colline du Parlement le 15 février. La feuille d’érable était déjà un symbole canadien bien établi.",en:"The maple leaf flag was officially proclaimed on 28 January 1965 and first raised on Parliament Hill on 15 February. The maple leaf was already a well-established Canadian symbol.",source:"https://www.canada.ca/en/canadian-heritage/services/flag-canada-history.html"},
    CAF:{fr:"La République centrafricaine associe le rouge-jaune-vert panafricain au bleu-blanc-rouge français, traversés par une bande rouge verticale.",en:"The Central African Republic combines pan-African red-yellow-green with the blue-white-red of France, crossed by a vertical red stripe.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/central-african-republic/flag/"},
    TCD:{fr:"Le tricolore bleu-jaune-rouge du Tchad ressemble énormément à celui de la Roumanie ; la principale différence visuelle est la nuance de bleu.",en:"Chad’s blue-yellow-red tricolour is extremely similar to Romania’s; the principal visual difference is the shade of blue.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/chad/flag/"},
    CHL:{fr:"L’étoile blanche est appelée « étoile solitaire » ; le Chili utilise sa composition familière avec canton bleu et bandes blanche et rouge depuis 1817.",en:"The white star is known as the “Lone Star”; Chile’s flag has used its familiar blue canton and white-over-red bands since 1817.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/chile/flag/"},
    CHN:{fr:"La grande étoile représente le Parti communiste chinois, accompagnée de quatre petites étoiles sur le champ rouge.",en:"The large star represents the Communist Party of China, with four smaller stars arranged beside it on the red field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/china/flag/"},
    COL:{fr:"La bande jaune occupe la moitié de la hauteur du drapeau, tandis que le bleu et le rouge n’en occupent chacun qu’un quart.",en:"The yellow band occupies half the flag’s height, while blue and red each occupy a quarter, making Colombia’s tricolour deliberately unequal.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/colombia/flag/"},
    COM:{fr:"Les quatre étoiles et les quatre bandes colorées représentent les quatre îles revendiquées par l’Union des Comores, dont Mayotte.",en:"The four stars and four coloured stripes represent the four islands claimed by the Union of the Comoros, including Mayotte.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/comoros/flag/"},
    COG:{fr:"La République du Congo utilise un rare tricolore diagonal : le vert et le rouge sont séparés par une large bande jaune.",en:"The Republic of the Congo uses a rare diagonal tricolour: green and red are separated by a broad yellow band.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/congo-republic-of-the/flag/"},
    CRI:{fr:"Le Costa Rica ajoute le bleu-blanc-rouge à son drapeau en 1848, en partie inspiré par les idéaux de la Révolution française.",en:"Costa Rica added blue-white-red to its flag in 1848, inspired in part by the ideals of the French Revolution.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/costa-rica/flag/"},
    CIV:{fr:"Le tricolore vertical orange-blanc-vert de la Côte d’Ivoire ressemble à celui de l’Irlande, mais avec les couleurs extérieures inversées.",en:"Côte d’Ivoire’s orange-white-green vertical tricolour resembles Ireland’s with the outer colours reversed.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/cote-divoire/flag/"},
    HRV:{fr:"Le tricolore rouge-blanc-bleu de la Croatie porte un damier surmonté d’une couronne de cinq petits écus historiques régionaux.",en:"Croatia’s red-white-blue tricolour carries a chequered shield topped by a crown of five smaller historic regional shields.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/croatia/flag/"},
    CUB:{fr:"L’étoile blanche dans le triangle rouge de Cuba est appelée La Estrella Solitaria, « l’étoile solitaire ».",en:"The lone white star in Cuba’s red triangle is known as La Estrella Solitaria, the Lone Star.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/cuba/flag/"},
    CYP:{fr:"Chypre est l’un des rares États dont le drapeau montre une carte du pays lui-même, au-dessus de deux branches d’olivier.",en:"Cyprus is one of the few states whose flag shows a map of the country itself, above two olive branches.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/cyprus/flag/"},
    CZE:{fr:"Le triangle bleu est ajouté aux anciennes couleurs blanche et rouge de Bohême en 1920, créant le drapeau ensuite conservé par la République tchèque.",en:"The blue triangle was added to the older white-and-red Bohemian colours in 1920, creating the flag later retained by the Czech Republic.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/czechia/flag/"},
    COD:{fr:"Le drapeau de la République démocratique du Congo comporte une étoile jaune et une bande diagonale rouge bordée de jaune sur fond bleu ciel.",en:"The Democratic Republic of the Congo’s flag features a yellow star and a red diagonal band edged in yellow across a sky-blue field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/congo-democratic-republic-of-the/flag/"},
    DNK:{fr:"Le Dannebrog danois est souvent présenté comme le plus ancien drapeau national encore utilisé sans interruption, avec sa croix nordique blanche sur rouge.",en:"Denmark’s Dannebrog is often described as the world’s oldest continuously used national flag, with its white Nordic cross on red.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/denmark/flag/"},
    DJI:{fr:"Le drapeau de Djibouti associe des bandes horizontales bleue et verte à un triangle blanc portant une étoile rouge à cinq branches.",en:"Djibouti’s flag combines blue and green horizontal bands with a white triangle bearing a red five-pointed star.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/djibouti/flag/"},
    DMA:{fr:"La Dominique est unique parmi les drapeaux nationaux par l’usage très visible du violet, présent sur le perroquet sisserou au centre.",en:"Dominica’s flag is unique among national flags for prominently featuring purple, visible on the sisserou parrot at its centre.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/dominica/flag/"},
    DOM:{fr:"La croix blanche de la République dominicaine divise le drapeau en quatre quartiers, avec les armoiries nationales au centre.",en:"The Dominican Republic’s white cross divides the flag into four quarters, with the national coat of arms placed at the centre.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/dominican-republic/flag/"},
    ECU:{fr:"Le drapeau équatorien partage le jaune-bleu-rouge de la Grande Colombie ; la version d’État se distingue par les armoiries au centre.",en:"Ecuador’s flag shares the yellow-blue-red colours of Gran Colombia; the state flag is distinguished by the coat of arms at the centre.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/ecuador/flag/"},
    EGY:{fr:"L’aigle de Saladin se trouve au centre du tricolore rouge-blanc-noir issu des couleurs de la Libération arabe.",en:"Egypt’s eagle of Saladin stands in the centre of the red-white-black Arab Liberation tricolour.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/egypt/flag/"},
    SLV:{fr:"Les armoiries du Salvador montrent cinq volcans représentant les cinq membres d’origine de la République fédérale d’Amérique centrale.",en:"El Salvador’s blue-white-blue flag carries a coat of arms with five volcanoes representing the five original members of the Federal Republic of Central America.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/el-salvador/flag/"},
    GNQ:{fr:"Le drapeau de la Guinée équatoriale montre un fromager sur ses armoiries, rappelant le lieu traditionnellement associé à un ancien traité avec l’Espagne.",en:"Equatorial Guinea’s flag includes a silk-cotton tree on its coat of arms, recalling the site traditionally associated with an early treaty with Spain.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/equatorial-guinea/flag/"},
    ERI:{fr:"Le triangle rouge de l’Érythrée contient une couronne d’olivier jaune, dérivée de l’emblème utilisé pendant la période de fédération avec l’ONU.",en:"Eritrea’s red triangle contains a yellow olive wreath, derived from the emblem used on the territory’s flag during the UN federation period.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/eritrea/flag/"},
    EST:{fr:"Le tricolore bleu-noir-blanc de l’Estonie devient un symbole national au XIXe siècle dans les mouvements étudiants et d’éveil national.",en:"Estonia’s blue-black-white tricolour first became a national symbol in the 19th-century student and national awakening movements.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/estonia/flag/"},
    SWZ:{fr:"Le drapeau de l’Eswatini centre un bouclier nguni traditionnel avec des lances et un bâton de combat, reflet de l’héritage swazi.",en:"Eswatini’s flag centres a traditional Nguni shield with spears and a fighting staff, reflecting the country’s Swazi heritage.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/eswatini/flag/"},
    ETH:{fr:"Les couleurs vert-jaune-rouge de l’Éthiopie ont eu une telle influence qu’elles ont inspiré de nombreux drapeaux panafricains ultérieurs.",en:"Ethiopia’s green-yellow-red colours became so influential that they inspired many later pan-African flags.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/ethiopia/flag/"},
    FJI:{fr:"Les Fidji ont conservé l’Union Jack après être devenues une république ; leur écu montre aussi des symboles agricoles comme la canne à sucre et les noix de coco.",en:"Fiji retained the Union Jack after becoming a republic; its shield also features agricultural symbols including sugar cane and coconuts.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/fiji/flag/"},
    FIN:{fr:"La croix nordique bleue de la Finlande sur fond blanc est souvent associée aux lacs du pays et à ses paysages enneigés.",en:"Finland’s blue Nordic cross on white is often associated with the country’s lakes and snowy landscape.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/finland/flag/"},
    FRA:{fr:"Le bleu et le rouge viennent des couleurs de Paris, tandis que le blanc était associé à la monarchie. Le tricolore prend sa disposition actuelle — bleu, blanc, rouge en bandes verticales — en 1794.",en:"Blue and red came from the colours of Paris, while white was associated with the monarchy. The tricolour took its current blue-white-red vertical form in 1794.",source:"https://www.elysee.fr/la-presidence/le-drapeau-francais"},
    GAB:{fr:"Le tricolore horizontal vert-jaune-bleu du Gabon est adopté à l’indépendance en 1960 et n’utilise pas le rouge panafricain.",en:"Gabon’s green-yellow-blue horizontal tricolour was adopted at independence in 1960 and does not use the pan-African red.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/gabon/flag/"},
    GMB:{fr:"Le drapeau de la Gambie a des bandes rouge, bleue et verte séparées par de fines lignes blanches ; le bleu représente le fleuve Gambie.",en:"The Gambia’s flag has red, blue and green bands separated by narrow white stripes; the blue band represents the Gambia River.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/gambia-the/flag/"},
    GEO:{fr:"Le « drapeau aux cinq croix » de la Géorgie porte une grande croix de saint Georges et quatre petites croix ; il redevient drapeau national en 2004.",en:"Georgia’s “five-cross flag” has a large red Saint George’s Cross with four smaller crosses and was restored as the national flag in 2004.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/georgia/flag/"},
    DEU:{fr:"Le noir, le rouge et l’or deviennent au XIXe siècle des couleurs associées à l’unité nationale et aux libertés civiques, notamment lors de la révolution de 1848-1849. Leur origine exacte reste toutefois incertaine.",en:"Black, red and gold became associated in the 19th century with national unity and civil freedom, especially during the 1848–49 revolution. Their exact origin, however, remains uncertain.",source:"https://www.bundestag.de/en/parliament/symbols/flag"},
    GHA:{fr:"Le Ghana fut le premier pays indépendant d’Afrique subsaharienne à adopter les couleurs panafricaines rouge-jaune-vert avec une étoile noire.",en:"Ghana was the first independent sub-Saharan African country to adopt the red-yellow-green pan-African colours with a black star.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/ghana/flag/"},
    GRC:{fr:"Le drapeau grec comporte neuf bandes horizontales et une croix blanche dans un canton bleu ; la signification historique précise des neuf bandes reste débattue.",en:"Greece’s flag has nine horizontal stripes and a white cross in a blue canton; the precise historical meaning of the nine stripes is debated.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/greece/flag/"},
    GRD:{fr:"Le drapeau de la Grenade contient sept étoiles pour ses sept paroisses et un petit symbole de noix de muscade, culture longtemps associée à l’île.",en:"Grenada’s flag contains seven stars for its seven parishes and a small nutmeg symbol, reflecting a crop long associated with the island.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/grenada/flag/"},
    GTM:{fr:"Le drapeau bleu-blanc-bleu du Guatemala est vertical et non horizontal ; ses armoiries comportent le quetzal, oiseau national.",en:"Guatemala’s blue-white-blue flag is vertical rather than horizontal; the coat of arms includes the quetzal, the national bird.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/guatemala/flag/"},
    GIN:{fr:"La Guinée utilise les couleurs panafricaines rouge-jaune-vert en bandes verticales, dans l’ordre inverse du tricolore du Mali voisin.",en:"Guinea uses the pan-African red-yellow-green colours in vertical bands, the reverse order of neighbouring Mali’s tricolour.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/guinea/flag/"},
    GNB:{fr:"Le drapeau de la Guinée-Bissau combine une bande verticale rouge avec des bandes horizontales jaune et verte et une étoile noire.",en:"Guinea-Bissau’s flag combines a red vertical band with yellow and green horizontal bands and a black star.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/guinea-bissau/flag/"},
    GUY:{fr:"Le drapeau du Guyana est surnommé « Golden Arrowhead » en raison du long triangle doré pointant vers le battant.",en:"Guyana’s flag is nicknamed the Golden Arrowhead because of the long golden triangle pointing toward the fly.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/guyana/flag/"},
    HTI:{fr:"Le drapeau civil d’Haïti est bleu sur rouge ; la version d’État ajoute les armoiries nationales dans un panneau blanc.",en:"Haiti’s civil flag is a blue-over-red bicolour; the state version adds the national coat of arms in a white panel.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/haiti/flag/"},
    HND:{fr:"Les cinq étoiles du drapeau du Honduras rappellent les cinq pays de l’ancienne République fédérale d’Amérique centrale.",en:"The five stars on Honduras’s flag recall the five countries of the former Federal Republic of Central America.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/honduras/flag/"},
    HUN:{fr:"Le tricolore horizontal rouge-blanc-vert de la Hongrie vient de couleurs utilisées depuis longtemps dans les armes historiques et le mouvement national.",en:"Hungary’s red-white-green horizontal tricolour grew from colours long used in the country’s historic arms and national movement.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/hungary/flag/"},
    ISL:{fr:"Le drapeau bleu de l’Islande utilise une croix nordique rouge bordée de blanc, reliant son dessin à la tradition vexillologique scandinave.",en:"Iceland’s blue flag uses a white-edged red Nordic cross, linking its design to the wider Scandinavian flag tradition.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/iceland/flag/"},
    IND:{fr:"Le chakra d’Ashoka bleu marine au centre comporte 24 rayons et provient du chapiteau aux lions d’Ashoka à Sarnath.",en:"The navy-blue Ashoka Chakra at the centre has 24 spokes and comes from the Lion Capital of Ashoka at Sarnath.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/india/flag/"},
    IDN:{fr:"Le simple bicolore rouge sur blanc de l’Indonésie s’appelle Sang Merah Putih et fut officiellement adopté lors de la proclamation d’indépendance en 1945.",en:"Indonesia’s simple red-over-white bicolour is called Sang Merah Putih and was formally adopted when independence was proclaimed in 1945.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/indonesia/flag/"},
    IRN:{fr:"Le mot « Allah » forme l’emblème rouge central, tandis qu’une forme stylisée de « Allahu Akbar » se répète le long des bords de la bande blanche.",en:"The word “Allah” forms the red central emblem, while a stylised “Allahu Akbar” is repeated along the borders of the white stripe.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/iran/flag/"},
    IRQ:{fr:"Le tricolore rouge-blanc-noir de l’Irak porte la formule arabe « Allahu Akbar » en écriture verte de style coufique.",en:"Iraq’s red-white-black tricolour carries the Arabic phrase “Allahu Akbar” in green Kufic-style script.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/iraq/flag/"},
    IRL:{fr:"Le tricolore vert-blanc-orange de l’Irlande devait symboliser la paix entre les traditions associées au vert et à l’orange.",en:"Ireland’s green-white-orange tricolour was intended to symbolise peace between traditions associated with green and orange.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/ireland/flag/"},
    ISR:{fr:"Les bandes bleues s’inspirent du talit, châle de prière juif traditionnel, avec l’étoile de David au centre.",en:"The blue stripes were inspired by the traditional Jewish prayer shawl, the tallit, with the Star of David at the centre.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/israel/flag/"},
    ITA:{fr:"Le tricolore vert-blanc-rouge italien apparaît à l’époque napoléonienne et devient un symbole central de l’unification italienne.",en:"Italy’s green-white-red tricolour emerged during the Napoleonic era and became a central symbol of Italian unification.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/italy/flag/"},
    JAM:{fr:"La Jamaïque est le seul drapeau national actuel sans rouge, blanc ni bleu : il utilise un sautoir doré avec des champs verts et noirs.",en:"Jamaica’s flag is the only current national flag without red, white or blue, using a gold saltire with green and black fields.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/jamaica/flag/"},
    JPN:{fr:"Le drapeau japonais est appelé Nisshōki, ou Hinomaru ; son disque rouge représente le soleil, symbole profondément lié à l’identité du Japon.",en:"Japan’s flag is known as the Nisshōki, or Hinomaru; its red disc represents the sun, a symbol deeply tied to Japan’s identity.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/japan/flag/"},
    JOR:{fr:"L’étoile blanche à sept branches de la Jordanie est associée aux sept versets de la première sourate du Coran et à l’unité arabe.",en:"Jordan’s seven-pointed white star is associated with the seven verses of the opening surah of the Quran and Arab unity.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/jordan/flag/"},
    KAZ:{fr:"Le drapeau bleu ciel du Kazakhstan montre un soleil doré au-dessus d’un aigle des steppes, avec un motif ornemental traditionnel près de la hampe.",en:"Kazakhstan’s sky-blue flag features a golden sun above a soaring steppe eagle, with a traditional ornamental pattern at the hoist.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/kazakhstan/flag/"},
    KEN:{fr:"Le drapeau du Kenya place un bouclier massaï et des lances croisées au centre de bandes noires, rouges et vertes bordées de blanc.",en:"Kenya’s flag places a Maasai shield and crossed spears at the centre of black, red and green bands edged in white.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/kenya/flag/"},
    KIR:{fr:"Le drapeau de Kiribati montre une frégate au-dessus d’un soleil levant et de vagues bleues et blanches représentant l’océan Pacifique.",en:"Kiribati’s flag shows a frigatebird flying above a rising sun and blue-and-white waves representing the Pacific Ocean.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/kiribati/flag/"},
    KWT:{fr:"Les bandes horizontales verte, blanche et rouge du Koweït sont rejointes par un trapèze noir à la hampe, utilisant les quatre couleurs panarabes.",en:"Kuwait’s green-white-red horizontal bands are joined by a black trapezoid at the hoist, using the four pan-Arab colours.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/kuwait/flag/"},
    KGZ:{fr:"Le soleil jaune du Kirghizistan a 40 rayons traditionnellement associés aux 40 tribus de l’épopée de Manas ; son centre représente le toit d’une yourte.",en:"Kyrgyzstan’s red flag centres a yellow sun whose 40 rays traditionally refer to the 40 tribes united in the epic of Manas; the centre depicts a yurt roof.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/kyrgyzstan/flag/"},
    LAO:{fr:"Le Laos est le seul État communiste actuel dont le drapeau national ne comporte pas d’étoile : un disque blanc repose sur une large bande bleue.",en:"Laos is the only current communist state whose national flag does not feature a star; a white disc sits on a broad blue band.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/laos/flag/"},
    LVA:{fr:"Le dessin carmin-blanc-carmin de la Lettonie s’appuie sur une bannière décrite dans une chronique du XIIIe siècle.",en:"Latvia’s dark carmine-white-carmine design is based on a banner described in a 13th-century chronicle.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/latvia/flag/"},
    LBN:{fr:"Le cèdre du Liban est un ancien symbole régional ; il apparaît en vert entre deux bandes rouges.",en:"Lebanon’s cedar tree is an ancient regional symbol and appears in green between two red bands.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/lebanon/flag/"},
    LSO:{fr:"Le drapeau du Lesotho présente au centre un mokorotlo noir, le chapeau traditionnel basotho.",en:"Lesotho’s flag features a black mokorotlo, the traditional Basotho hat, at the centre.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/lesotho/flag/"},
    LBR:{fr:"Le drapeau du Liberia rappelle volontairement celui des États-Unis, reflet de son histoire avec des colons venus d’Amérique ; il comporte 11 bandes et une étoile.",en:"Liberia’s flag deliberately echoes the US flag, reflecting the country’s history with settlers from the United States; it has 11 stripes and one star.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/liberia/flag/"},
    LBY:{fr:"La Libye rétablit en 2011 son drapeau rouge-noir-vert au croissant et à l’étoile, déjà utilisé par le royaume de 1951 à 1969.",en:"Libya restored its red-black-green flag with crescent and star in 2011; the same design had represented the kingdom from 1951 to 1969.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/libya/flag/"},
    LIE:{fr:"Le Liechtenstein ajoute la couronne dorée à son drapeau bleu-rouge en 1937 après avoir découvert aux JO de 1936 qu’il était identique au drapeau civil d’Haïti.",en:"Liechtenstein added the golden crown to its blue-red flag in 1937 after discovering at the 1936 Olympics that its flag was identical to Haiti’s civil flag.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/liechtenstein/flag/"},
    LTU:{fr:"Le tricolore jaune-vert-rouge de la Lituanie est adopté une première fois en 1918 puis restauré en 1988 pendant le mouvement vers le retour à l’indépendance.",en:"Lithuania’s yellow-green-red tricolour was first adopted in 1918 and restored in 1988 during the movement toward renewed independence.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/lithuania/flag/"},
    LUX:{fr:"Le tricolore rouge-blanc-bleu clair du Luxembourg ressemble au drapeau néerlandais, mais utilise traditionnellement un bleu nettement plus clair.",en:"Luxembourg’s red-white-light-blue tricolour resembles the Dutch flag, but traditionally uses a noticeably lighter shade of blue.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/luxembourg/flag/"},
    MDG:{fr:"Le drapeau de Madagascar associe une bande blanche verticale à des bandes horizontales rouge et verte, couleurs liées au royaume merina et au mouvement indépendantiste.",en:"Madagascar’s flag combines a vertical white band with horizontal red and green bands, colours linked to the island’s historic Merina kingdom and independence movement.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/madagascar/flag/"},
    MWI:{fr:"Le soleil rouge levant du Malawi symbolise l’aube de l’espoir et de la liberté pour l’Afrique ; le dessin original de 1964 a été restauré en 2012.",en:"Malawi’s rising red sun symbolises the dawn of hope and freedom for Africa; the original 1964 design was restored in 2012.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/malawi/flag/"},
    MYS:{fr:"Les 14 bandes et l’étoile à 14 branches de la Malaisie représentent les 13 États de la fédération avec le gouvernement fédéral.",en:"Malaysia’s 14 stripes and 14-point star represent the federation’s 13 states together with the federal government.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/malaysia/flag/"},
    MDV:{fr:"Les Maldives placent un croissant blanc sur un rectangle vert dans un champ rouge, le croissant reflétant l’identité islamique du pays.",en:"The Maldives places a white crescent on a green rectangle within a red field, with the crescent reflecting the country’s Islamic identity.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/maldives/flag/"},
    MLI:{fr:"Le tricolore vertical vert-jaune-rouge du Mali utilise les couleurs panafricaines et est adopté sous sa forme actuelle en 1961.",en:"Mali’s green-yellow-red vertical tricolour uses the pan-African colours and was adopted in its present form in 1961.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/mali/flag/"},
    MLT:{fr:"La croix de George dans le canton supérieur rappelle la décoration accordée par le roi George VI à Malte pour son courage pendant la Seconde Guerre mondiale.",en:"The George Cross in the upper hoist commemorates the decoration awarded by King George VI to Malta for its bravery during the Second World War.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/malta/flag/"},
    MHL:{fr:"Les rayons orange et blanc des Îles Marshall s’élargissent vers le battant, tandis que l’étoile à 24 pointes représente les districts électoraux du pays.",en:"The Marshall Islands’ orange and white rays widen toward the fly, while the 24-point star represents the country’s electoral districts.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/marshall-islands/flag/"},
    MRT:{fr:"Le drapeau vert de la Mauritanie au croissant et à l’étoile dorés reçoit des bandes rouges en haut et en bas après un référendum en 2017.",en:"Mauritania’s green flag with a gold crescent and star gained red bands at the top and bottom after a 2017 referendum.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/mauritania/flag/"},
    MUS:{fr:"Le drapeau de Maurice comporte quatre bandes horizontales — rouge, bleue, jaune et verte — et est souvent surnommé « Les Quatre Bandes ».",en:"Mauritius’s flag has four horizontal bands—red, blue, yellow and green—and is often nicknamed “Les Quatre Bandes”.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/mauritius/flag/"},
    MEX:{fr:"Le drapeau actuel conserve les bandes verticales verte, blanche et rouge et les armoiries au centre : un aigle sur un cactus tenant un serpent. Les caractéristiques du modèle actuel ont été fixées en 1968.",en:"The current flag keeps the green, white and red vertical bands with the coat of arms at the centre: an eagle on a cactus holding a snake. The characteristics of the current design were set in 1968.",source:"https://www.gob.mx/sre/articulos/learn-about-the-history-of-the-mexican-flag-esmibandera"},
    FSM:{fr:"Les quatre étoiles blanches du drapeau des États fédérés de Micronésie représentent leurs quatre États : Yap, Chuuk, Pohnpei et Kosrae.",en:"The four white stars on the Federated States of Micronesia flag represent its four states: Yap, Chuuk, Pohnpei and Kosrae.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/micronesia-federated-states-of/flag/"},
    MDA:{fr:"Le tricolore bleu-jaune-rouge de la Moldavie porte ses armoiries, dont une tête d’aurochs, sur la bande centrale.",en:"Moldova’s blue-yellow-red tricolour carries its coat of arms, including an aurochs head, on the central band.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/moldova/flag/"},
    MCO:{fr:"Le bicolore rouge sur blanc de Monaco utilise les couleurs traditionnelles de la maison Grimaldi, employées sous des formes proches depuis des siècles.",en:"Monaco’s red-over-white bicolour uses the traditional colours of the House of Grimaldi and has been in use in similar form for centuries.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/monaco/flag/"},
    MNG:{fr:"Le symbole Soyombo apparaît près de la hampe du drapeau rouge-bleu-rouge de Mongolie et rassemble plusieurs signes géométriques et cosmiques traditionnels.",en:"Mongolia’s Soyombo symbol appears on the hoist side of its red-blue-red flag and contains several traditional geometric and cosmic symbols.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/mongolia/flag/"},
    MNE:{fr:"Le drapeau rouge du Monténégro est bordé d’or et porte les armoiries de l’État avec un aigle bicéphale doré.",en:"Montenegro’s red flag is bordered in gold and carries the state coat of arms with a golden double-headed eagle.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/montenegro/flag/"},
    MAR:{fr:"L’étoile verte à cinq branches entrelacées du Maroc, appelée sceau de Salomon, est ajoutée au drapeau rouge en 1915.",en:"Morocco’s green five-pointed interlaced star, known as the Seal of Solomon, was added to the red flag in 1915.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/morocco/flag/"},
    MOZ:{fr:"Le Mozambique est le seul pays dont le drapeau national représente une arme à feu moderne : un fusil de type AK figure avec une houe et un livre.",en:"Mozambique is the only national flag to depict a modern firearm: an AK-style rifle appears in the emblem with a hoe and book.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/mozambique/flag/"},
    MMR:{fr:"Le Myanmar adopte son tricolore jaune-vert-rouge actuel avec une grande étoile blanche en 2010, remplaçant le drapeau de l’époque socialiste.",en:"Myanmar adopted its current yellow-green-red tricolour with a large white star in 2010, replacing the previous socialist-era flag.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/burma/flag/"},
    NAM:{fr:"Le drapeau namibien est traversé en diagonale par une bande rouge bordée de blanc, avec un soleil doré dans le champ bleu supérieur.",en:"Namibia’s flag is crossed diagonally by a red band edged in white, with a golden sun in the upper blue field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/namibia/flag/"},
    NRU:{fr:"La fine ligne jaune de Nauru représente l’équateur ; l’étoile blanche à 12 branches est placée juste en dessous car l’île se situe légèrement au sud.",en:"Nauru’s thin yellow line represents the Equator, while the white 12-pointed star sits just below it because the island lies slightly south of the Equator.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/nauru/flag/"},
    NPL:{fr:"Le Népal est le seul État souverain dont le drapeau national n’est pas quadrilatère ; ses deux fanions superposés portent une lune et un soleil stylisés.",en:"Nepal is the only sovereign state with a national flag that is not quadrilateral; its two stacked pennants carry stylised moon and sun symbols.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/nepal/flag/"},
    NLD:{fr:"Aux Pays-Bas, la bande orange d’origine du « drapeau du Prince » a progressivement été remplacée par le rouge, donnant le tricolore rouge-blanc-bleu actuel.",en:"The Netherlands replaced the original orange top stripe of the Prince’s Flag with red over time, producing the familiar red-white-blue tricolour.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/netherlands/flag/"},
    NZL:{fr:"Conçu en 1869, le drapeau associe l’Union Jack aux quatre étoiles rouges de la Croix du Sud. Sa description officielle a été publiée dans la New Zealand Gazette en 1902.",en:"Designed in 1869, the flag combines the Union Jack with four red stars of the Southern Cross. Its official description was published in the New Zealand Gazette in 1902.",source:"https://www.mch.govt.nz/our-work/flags-anthems-and-emblems/new-zealand-flag"},
    NIC:{fr:"Les armoiries du Nicaragua montrent cinq volcans pour les cinq républiques centraméricaines d’origine, sous un arc-en-ciel et un bonnet de la liberté.",en:"Nicaragua’s coat of arms shows five volcanoes for the five original Central American republics beneath a rainbow and liberty cap.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/nicaragua/flag/"},
    NER:{fr:"Le tricolore orange-blanc-vert du Niger comporte un disque orange au centre, souvent interprété comme le soleil.",en:"Niger’s orange-white-green tricolour includes an orange disc in the centre; interpretations of the disc include the sun.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/niger/flag/"},
    NGA:{fr:"Le drapeau vert-blanc-vert du Nigeria fut dessiné par l’étudiant Michael Taiwo Akinkunmi pour un concours national avant l’indépendance de 1960.",en:"Nigeria’s green-white-green flag was designed by student Michael Taiwo Akinkunmi for a national competition before independence in 1960.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/nigeria/flag/"},
    PRK:{fr:"Le drapeau nord-coréen place une étoile rouge dans un disque blanc près de la hampe, sur une large bande rouge bordée de blanc et de bleu.",en:"North Korea’s flag places a red star inside a white disc near the hoist on a broad red central band edged in white and blue.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/korea-north/flag/"},
    MKD:{fr:"Le drapeau de la Macédoine du Nord montre un soleil jaune stylisé à huit larges rayons allant jusqu’aux bords d’un champ rouge.",en:"North Macedonia’s flag shows a stylised yellow sun with eight broad rays extending to the edges of a red field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/north-macedonia/flag/"},
    NOR:{fr:"Le drapeau rouge de la Norvège à croix nordique bleue bordée de blanc est dessiné en 1821 et combine des couleurs associées au Danemark et à la Suède.",en:"Norway’s red flag with a blue Nordic cross outlined in white was designed in 1821 and combines colours associated with Denmark and Sweden.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/norway/flag/"},
    OMN:{fr:"Le drapeau d’Oman porte l’emblème national — deux épées croisées et un poignard khanjar — en haut de la bande rouge verticale.",en:"Oman’s flag carries the national emblem—crossed swords and a khanjar dagger—at the top of the vertical red band.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/oman/flag/"},
    PAK:{fr:"Le croissant et l’étoile blancs du Pakistan reposent sur un champ vert foncé, tandis que la bande blanche à la hampe représente les minorités religieuses.",en:"Pakistan’s white crescent and star stand on a dark green field, while the white stripe at the hoist represents religious minorities.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/pakistan/flag/"},
    PLW:{fr:"Le disque doré du drapeau des Palaos représente une pleine lune, et non un soleil ; il est légèrement décentré sur un fond bleu clair.",en:"Palau’s golden disc is a full moon rather than a sun, placed slightly off-centre on a light-blue field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/palau/flag/"},
    PSE:{fr:"Le drapeau palestinien utilise les couleurs panarabes : bandes horizontales noire, blanche et verte avec un triangle rouge à la hampe.",en:"The Palestinian flag uses the pan-Arab colours in black, white and green horizontal bands with a red triangle at the hoist.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/west-bank/flag/"},
    PAN:{fr:"Le drapeau en quartiers du Panama comporte deux étoiles et des champs rouge, blanc et bleu ; son dessin date de la séparation d’avec la Colombie en 1903.",en:"Panama’s quartered flag has two stars and red, white and blue fields; the design dates from the period of separation from Colombia in 1903.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/panama/flag/"},
    PNG:{fr:"Le drapeau diagonal de la Papouasie-Nouvelle-Guinée associe la Croix du Sud à un oiseau de paradis doré, important symbole national.",en:"Papua New Guinea’s diagonal flag combines the Southern Cross with a golden bird-of-paradise, a major national symbol.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/papua-new-guinea/flag/"},
    PRY:{fr:"Le Paraguay est inhabituel : les deux faces du drapeau portent des emblèmes différents, les armoiries nationales à l’avers et le sceau du Trésor au revers.",en:"Paraguay is unusual in having different emblems on the two sides of its national flag: the national coat of arms on the front and the Treasury seal on the reverse.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/paraguay/flag/"},
    PER:{fr:"Le tribande vertical rouge-blanc-rouge du Pérou date des débuts de la République ; la version d’État ajoute les armoiries nationales au centre.",en:"Peru’s red-white-red vertical triband dates from the early republic; the state version adds the national coat of arms in the centre.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/peru/flag/"},
    PHL:{fr:"En temps de guerre, les Philippines retournent officiellement leur drapeau pour placer la bande rouge au-dessus de la bleue, une convention très rare.",en:"The Philippines turns its flag upside down in wartime, placing the red stripe above the blue; this official convention is highly unusual.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/philippines/flag/"},
    POL:{fr:"Le bicolore blanc sur rouge de la Pologne vient des couleurs héraldiques de ses armoiries : un aigle blanc sur fond rouge.",en:"Poland’s white-over-red bicolour comes from the heraldic colours of the Polish coat of arms: a white eagle on a red field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/poland/flag/"},
    PRT:{fr:"Le drapeau portugais place les armoiries nationales sur une sphère armillaire à la frontière entre le vert et le rouge.",en:"Portugal’s flag places the national coat of arms over an armillary sphere at the boundary between green and red.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/portugal/flag/"},
    QAT:{fr:"Le champ bordeaux du Qatar est séparé du blanc par neuf pointes dentelées ; ses proportions particulièrement allongées rendent aussi le drapeau distinctif.",en:"Qatar’s maroon field is separated from white by nine serrated points; its unusually long proportions also make the flag distinctive.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/qatar/flag/"},
    ROU:{fr:"Le tricolore vertical bleu-jaune-rouge de la Roumanie date du XIXe siècle et devient un symbole du mouvement révolutionnaire de 1848.",en:"Romania’s blue-yellow-red vertical tricolour dates from the 19th century and became a symbol of the 1848 revolutionary movement.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/romania/flag/"},
    RUS:{fr:"Le tricolore blanc-bleu-rouge de la Russie remonte à la fin du XVIIe siècle et redevient drapeau national après la période soviétique.",en:"Russia’s white-blue-red tricolour has roots in the late 17th century and was restored as the national flag after the Soviet period.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/russia/flag/"},
    RWA:{fr:"Le Rwanda adopte son drapeau bleu-jaune-vert actuel en 2001 ; un soleil doré à 24 rayons figure dans la partie supérieure au battant.",en:"Rwanda adopted its current blue-yellow-green flag in 2001; a golden sun with 24 rays appears in the upper fly.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/rwanda/flag/"},
    KNA:{fr:"Saint-Christophe-et-Niévès utilise une bande noire diagonale à deux étoiles blanches, séparant des champs vert et rouge bordés de jaune.",en:"Saint Kitts and Nevis uses a diagonal black band with two white stars, separating green and red fields edged in yellow.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/saint-kitts-and-nevis/flag/"},
    LCA:{fr:"Le drapeau de Sainte-Lucie est dominé par des triangles noir, blanc et or superposés, référence stylisée aux célèbres Pitons de l’île.",en:"Saint Lucia’s flag is dominated by layered black, white and gold triangles, a stylised reference to the island’s famous Pitons.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/saint-lucia/flag/"},
    VCT:{fr:"Saint-Vincent-et-les-Grenadines place trois losanges verts en V, liés dans la symbolique du drapeau au surnom « joyaux des Antilles ».",en:"Saint Vincent and the Grenadines places three green diamonds in a V formation, giving the country the nickname “Gems of the Antilles” in the flag’s symbolism.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/saint-vincent-and-the-grenadines/flag/"},
    WSM:{fr:"Le drapeau rouge des Samoa comporte un canton bleu avec cinq étoiles blanches formant la Croix du Sud.",en:"Samoa’s red flag has a blue canton bearing five white stars that form the Southern Cross.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/samoa/flag/"},
    SMR:{fr:"Le drapeau blanc et bleu clair de Saint-Marin porte des armoiries détaillées avec trois tours représentant les sommets du mont Titano.",en:"San Marino’s white-and-light-blue flag carries a detailed coat of arms with three towers representing the peaks of Monte Titano.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/san-marino/flag/"},
    STP:{fr:"Le drapeau de Sao Tomé-et-Principe utilise les couleurs panafricaines ; deux étoiles noires représentent les deux îles principales du pays.",en:"São Tomé and Príncipe’s flag uses pan-African colours, with two black stars representing the country’s two principal islands.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/sao-tome-and-principe/flag/"},
    SAU:{fr:"Le drapeau saoudien porte la chahada au-dessus d’un sabre blanc ; en raison de l’inscription sacrée, il n’est normalement ni verticalisé ni mis en berne.",en:"Saudi Arabia’s flag bears the shahada above a white sword; because of the sacred inscription, it is not normally flown vertically or at half-mast.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/saudi-arabia/flag/"},
    SEN:{fr:"Le tricolore vert-jaune-rouge du Sénégal comporte une étoile verte à cinq branches au centre de la bande jaune.",en:"Senegal’s green-yellow-red tricolour has a green five-pointed star at the centre of the yellow band.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/senegal/flag/"},
    SRB:{fr:"Le tricolore rouge-bleu-blanc de la Serbie porte les petites armoiries près de la hampe, avec notamment un aigle blanc à deux têtes.",en:"Serbia’s red-blue-white tricolour carries the lesser national coat of arms near the hoist, including a white double-headed eagle.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/serbia/flag/"},
    SYC:{fr:"Les cinq bandes colorées des Seychelles rayonnent en diagonale depuis le coin inférieur de la hampe, donnant au drapeau un aspect très dynamique.",en:"Seychelles’ five coloured bands radiate diagonally from the lower hoist, giving the flag a dynamic sunburst-like appearance.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/seychelles/flag/"},
    SLE:{fr:"Le tricolore horizontal vert-blanc-bleu de la Sierra Leone est adopté lors de l’indépendance en 1961.",en:"Sierra Leone’s green-white-blue horizontal tricolour was adopted at independence in 1961.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/sierra-leone/flag/"},
    SGP:{fr:"Le croissant de Singapour représente une jeune nation en essor ; les cinq étoiles symbolisent démocratie, paix, progrès, justice et égalité.",en:"Singapore’s crescent represents a young nation on the rise, while five stars stand for democracy, peace, progress, justice and equality.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/singapore/flag/"},
    SVK:{fr:"Le tricolore panslave blanc-bleu-rouge de la Slovaquie se distingue par un écu montrant une double croix blanche au-dessus de trois collines bleues.",en:"Slovakia’s white-blue-red pan-Slavic tricolour is distinguished by a shield showing a white double cross above three blue hills.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/slovakia/flag/"},
    SVN:{fr:"Les armoiries slovènes montrent le mont Triglav, des vagues représentant la mer et les rivières, ainsi que trois étoiles à six branches.",en:"Slovenia’s coat of arms shows Mount Triglav, waves representing the sea and rivers, and three six-pointed stars.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/slovenia/flag/"},
    SLB:{fr:"Le drapeau des Îles Salomon est divisé en diagonale par du jaune, avec cinq étoiles blanches sur bleu et un champ vert inférieur.",en:"The Solomon Islands’ flag is divided diagonally by yellow, with five white stars on blue and a green lower field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/solomon-islands/flag/"},
    SOM:{fr:"L’étoile blanche à cinq branches de l’unité devait à l’origine représenter cinq régions habitées par des populations somalies.",en:"The white five-pointed Star of Unity was originally intended to represent five regions inhabited by Somali people.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/somalia/flag/"},
    ZAF:{fr:"Dessiné par Fred Brownell, le drapeau actuel a été utilisé pour la première fois le 27 avril 1994. Sa forme centrale en Y peut être interprétée comme la convergence d’éléments divers avançant ensemble.",en:"Designed by Fred Brownell, the current flag was first used on 27 April 1994. Its central Y-shaped design can be read as diverse elements converging and moving forward together.",source:"https://www.gov.za/about-sa/national-flag-0"},
    KOR:{fr:"Le Taegeukgi sud-coréen centre un taegeuk rouge et bleu entouré de quatre trigrammes noirs issus de la tradition du Yi Jing.",en:"South Korea’s Taegeukgi centres a red-and-blue taegeuk surrounded by four black trigrams drawn from the I Ching tradition.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/korea-south/flag/"},
    SSD:{fr:"Le drapeau du Soudan du Sud combine noir, rouge, vert, blanc et bleu avec une étoile jaune ; il était déjà utilisé par le SPLM avant l’indépendance.",en:"South Sudan’s flag combines black, red, green, white and blue with a yellow star in a blue triangle; it was used by the SPLM before independence.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/south-sudan/flag/"},
    ESP:{fr:"Les armoiries espagnoles réunissent des symboles de plusieurs royaumes historiques, encadrés par les colonnes d’Hercule.",en:"Spain’s coat of arms brings together symbols of its historic kingdoms, while the Pillars of Hercules flank the shield.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/spain/flag/"},
    LKA:{fr:"Le drapeau du Sri Lanka présente un lion doré tenant une épée, avec quatre feuilles de bo dans les coins du panneau marron.",en:"Sri Lanka’s flag features a golden lion holding a sword, with four bo leaves in the corners of the maroon panel.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/sri-lanka/flag/"},
    SDN:{fr:"Le tricolore horizontal rouge-blanc-noir du Soudan et son triangle vert utilisent les quatre couleurs panarabes.",en:"Sudan’s red-white-black horizontal tricolour and green triangle use the four pan-Arab colours.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/sudan/flag/"},
    SUR:{fr:"La grande étoile jaune du Suriname se trouve sur une bande rouge entre des bandes vertes et blanches et est couramment associée à l’unité nationale.",en:"Suriname’s large yellow star sits on a red band between green and white stripes and is commonly associated with national unity.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/suriname/flag/"},
    SWE:{fr:"La croix nordique jaune de la Suède sur fond bleu est utilisée sous une forme reconnaissable depuis au moins le XVIe siècle.",en:"Sweden’s yellow Nordic cross on blue has been used in recognisable form since at least the 16th century.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/sweden/flag/"},
    CHE:{fr:"La Suisse est l’un des deux seuls États souverains à avoir un drapeau national carré ; sa croix blanche se détache sur fond rouge.",en:"Switzerland is one of only two sovereign states with a square national flag; its white cross stands on a red field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/switzerland/flag/"},
    SYR:{fr:"Le drapeau syrien a changé avec les régimes politiques ; les autorités actuelles ont adopté en 2025 un tricolore vert-blanc-noir à trois étoiles rouges.",en:"Syria’s flag has changed with political regimes; the current authorities adopted a green-white-black tricolour with three red stars in 2025.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/syria/flag/"},
    TJK:{fr:"Le drapeau du Tadjikistan place une couronne dorée surmontée de sept étoiles au centre d’une bande blanche entre rouge et vert.",en:"Tajikistan’s flag places a golden crown topped by seven stars in the centre of a white stripe between red and green.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/tajikistan/flag/"},
    TZA:{fr:"Le drapeau de la Tanzanie combine des couleurs du Tanganyika et de Zanzibar dans un dessin diagonal adopté lors de leur union en 1964.",en:"Tanzania’s flag combines colours from Tanganyika and Zanzibar in a diagonal design adopted when the two united in 1964.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/tanzania/flag/"},
    THA:{fr:"Le drapeau thaïlandais à cinq bandes rouge-blanc-bleu est appelé Trairong, « tricolore », et fut adopté en 1917.",en:"Thailand’s five-stripe red-white-blue flag is called the Trairong, meaning “tricolour”, and was adopted in 1917.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/thailand/flag/"},
    TLS:{fr:"Le drapeau du Timor oriental a deux triangles noir et jaune superposés à la hampe, avec une étoile blanche sur un champ rouge.",en:"Timor-Leste’s flag has overlapping black and yellow triangles at the hoist, with a white star on a red field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/timor-leste/flag/"},
    TGO:{fr:"Le drapeau du Togo comporte cinq bandes vertes et jaunes et un canton rouge à étoile blanche ; ses proportions utilisent le nombre d’or.",en:"Togo’s five green-and-yellow stripes are joined by a red canton with a white star; the proportions use the golden ratio.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/togo/flag/"},
    TON:{fr:"La Constitution des Tonga prévoit que le drapeau national ne doit jamais être modifié, donnant à sa croix rouge une protection constitutionnelle inhabituelle.",en:"Tonga’s constitution states that the national flag must never be altered, giving its red cross design unusual constitutional protection.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/tonga/flag/"},
    TTO:{fr:"Le drapeau de Trinité-et-Tobago est traversé par une bande noire diagonale bordée de blanc sur un champ rouge.",en:"Trinidad and Tobago’s flag is crossed by a black diagonal band edged in white across a red field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/trinidad-and-tobago/flag/"},
    TUN:{fr:"Le disque blanc de la Tunisie contient un croissant et une étoile rouges sur fond rouge, dessin dont les racines remontent au XIXe siècle.",en:"Tunisia’s white disc contains a red crescent and five-pointed star on a red field, a design with roots in the 19th century.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/tunisia/flag/"},
    TUR:{fr:"Le croissant et l’étoile blancs de la Turquie sur rouge dérivent des drapeaux ottomans ; la géométrie précise du drapeau moderne est fixée par la loi.",en:"Turkey’s white crescent and star on red developed from Ottoman-era flags; the exact geometry of the modern flag is fixed by law.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/turkey/flag/"},
    TKM:{fr:"Le drapeau du Turkménistan porte une bande verticale de motifs de tapis représentant cinq grands groupes traditionnels de tapis tribaux.",en:"Turkmenistan’s flag carries a vertical carpet-gul stripe representing five major traditional tribal carpet patterns.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/turkmenistan/flag/"},
    TUV:{fr:"Les neuf étoiles de Tuvalu représentent les neuf îles du pays et sont disposées approximativement selon leur position géographique.",en:"Tuvalu’s nine stars represent the country’s nine islands, arranged roughly according to their geographic positions.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/tuvalu/flag/"},
    UGA:{fr:"Le drapeau de l’Ouganda répète des bandes noires, jaunes et rouges et centre une grue royale, symbole national déjà utilisé à l’époque coloniale.",en:"Uganda’s flag repeats black, yellow and red stripes and centres a grey crowned crane, a national symbol also used during the colonial era.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/uganda/flag/"},
    UKR:{fr:"Le bicolore bleu sur jaune de l’Ukraine fut utilisé par le mouvement national ukrainien puis restauré comme drapeau national après l’indépendance de 1991.",en:"Ukraine’s blue-over-yellow bicolour was used by the Ukrainian national movement and was restored as the national flag after independence in 1991.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/ukraine/flag/"},
    ARE:{fr:"Les Émirats arabes unis adoptent leur drapeau panarabe rouge, vert, blanc et noir lors de la création de la fédération en 1971.",en:"The United Arab Emirates adopted its red, green, white and black pan-Arab flag at federation in 1971.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/united-arab-emirates/flag/"},
    GBR:{fr:"L’Union Flag combine en un seul dessin les croix associées aux saints patrons de l’Angleterre, de l’Écosse et de l’Irlande.",en:"The Union Flag combines the crosses associated with the patron saints of England, Scotland and Ireland into a single design.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/united-kingdom/flag/"},
    USA:{fr:"En 1777, le premier Flag Act fixe 13 bandes et 13 étoiles. Depuis 1818, les 13 bandes rappellent les colonies d’origine et une étoile est ajoutée pour chaque État ; le drapeau à 50 étoiles date de 1960.",en:"In 1777, the first Flag Act established 13 stripes and 13 stars. Since 1818, the 13 stripes honour the original colonies and one star is added for each state; the 50-star flag dates from 1960.",source:"https://www.si.edu/spotlight/flag-day/flag-facts"},
    URY:{fr:"Le Soleil de Mai de l’Uruguay renvoie à la révolution de Mai de 1810 ; les neuf bandes représentent les neuf départements d’origine du pays.",en:"Uruguay’s Sun of May refers to the May Revolution of 1810; the flag’s nine horizontal stripes represent the country’s original nine departments.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/uruguay/flag/"},
    UZB:{fr:"Le croissant et les 12 étoiles de l’Ouzbékistan apparaissent au-dessus de bandes blanche et verte séparées par de fines lignes rouges sur fond bleu.",en:"Uzbekistan’s crescent and 12 stars appear above white and green bands separated by thin red lines on a blue field.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/uzbekistan/flag/"},
    VUT:{fr:"Le drapeau du Vanuatu comporte une défense de sanglier et des feuilles de namele croisées dans le triangle noir, symboles importants de la culture locale.",en:"Vanuatu’s flag includes a boar’s tusk and crossed namele leaves inside the black triangle, important symbols in local culture.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/vanuatu/flag/"},
    VAT:{fr:"Le Vatican est l’un des deux seuls États souverains au drapeau carré ; la moitié blanche porte les clés croisées de saint Pierre sous la tiare papale.",en:"Vatican City is one of only two sovereign states with a square flag; the white half carries the crossed keys of Saint Peter beneath the papal tiara.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/holy-see-vatican-city/flag/"},
    VEN:{fr:"L’arc de huit étoiles blanches du Venezuela rappelle des provinces ayant soutenu l’indépendance ; la huitième étoile est ajoutée au drapeau moderne en 2006.",en:"Venezuela’s arc of eight white stars recalls provinces that supported independence; the eighth star was added to the modern flag in 2006.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/venezuela/flag/"},
    VNM:{fr:"La grande étoile jaune du Vietnam se détache sur un champ rouge ; ce dessin fut utilisé par le Viet Minh avant de devenir drapeau national.",en:"Vietnam’s large yellow five-pointed star stands on a red field; the design was used by the Viet Minh before becoming the national flag.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/vietnam/flag/"},
    YEM:{fr:"Le tricolore rouge-blanc-noir du Yémen vient des couleurs de la Libération arabe et est utilisé depuis l’unification du Nord et du Sud en 1990.",en:"Yemen’s red-white-black tricolour derives from the Arab Liberation colours and has been used since North and South Yemen unified in 1990.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/yemen/flag/"},
    ZMB:{fr:"La Zambie place son aigle et ses bandes verticales rouge-noir-orange près du battant plutôt qu’au centre, une disposition nationale inhabituelle.",en:"Zambia places its eagle and vertical red-black-orange stripes at the fly rather than the centre, an unusual national-flag layout.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/zambia/flag/"},
    ZWE:{fr:"Le drapeau du Zimbabwe montre l’Oiseau du Zimbabwe, inspiré de sculptures en stéatite trouvées au Grand Zimbabwe, au-dessus d’une étoile rouge.",en:"Zimbabwe’s flag includes the Zimbabwe Bird, taken from soapstone sculptures found at Great Zimbabwe, above a red star in a white triangle.",source:"https://www.cia.gov/the-world-factbook/about/archives/2024/countries/zimbabwe/flag/"}
  };
})(globalThis);
